-- The login banner and the minimap tooltip.
L["Click to open the settings"] = "Klicken, um die Einstellungen zu öffnen";
L["Circular class, spec and role icons on every nameplate, live crowd-control icons and instant Healer CC alerts."] = "Runde Klassen-, Spez- und Rollensymbole auf jedem Nameplate, live Kontrolleffekt-Symbole und sofortige Heiler-CC-Warnungen.";
L["OPlates only adds icons. Your nameplate addon keeps its own bars and style."] = "OPlates fügt nur Symbole hinzu. Dein Nameplate-Addon behält seine eigenen Balken und seinen Stil.";
L["Type %s or click the minimap button to open the settings."] = "Gib %s ein oder klicke auf die Minimap-Schaltfläche, um die Einstellungen zu öffnen.";
L["Open settings"] = "Einstellungen öffnen";
L["Test"] = "Test";
L["Hide"] = "Ausblenden";

-- The settings window.
L["|cffff3b3bWARMANE AND OTHER SERVERS THAT FORBID CLIENT MODIFICATIONS ARE NOT COMPATIBLE WITH awesome_wotlk OR ANY CLIENT PATCH. DO NOT INSTALL IT THERE.|r"] = "|cffff3b3bWARMANE UND ANDERE SERVER, DIE CLIENT-MODIFIKATIONEN VERBIETEN, SIND NICHT MIT awesome_wotlk ODER IRGENDEINEM CLIENT-PATCH KOMPATIBEL. INSTALLIERE IHN DORT NICHT.|r";
L["Your client is unpatched, so players reveal their class only after you mouseover them. The free FreakySphere awesome_wotlk client patch gives every visible player class colors, icons and borders instantly, with no mouseover at all. Copy the link below if you want it. OPlates runs fine without it."] = "Dein Client ist ungepatcht, daher zeigen Spieler ihre Klasse erst, wenn du sie mit der Maus überfährst. Der kostenlose Client-Patch awesome_wotlk von FreakySphere gibt jedem sichtbaren Spieler sofort Klassenfarben, Symbole und Rahmen, ganz ohne Mauszeiger. Kopiere den Link unten, wenn du ihn möchtest. OPlates läuft auch ohne ihn einwandfrei.";
L["OPlates now reads nameplate units straight from your client: every visible player gets class colors, icons and borders instantly, no mouseover needed. You can switch this off in /op > Advanced."] = "OPlates liest die Nameplate-Einheiten jetzt direkt aus deinem Client: jeder sichtbare Spieler bekommt sofort Klassenfarben, Symbole und Rahmen, ohne Mauszeiger. Du kannst das unter /op > Erweitert abschalten.";
L["Your client has the awesome_wotlk patch, but OPlates is not using its nameplate units, so you are missing instant class colors, icons and borders on every visible player. Turn it on now?"] = "Dein Client hat den awesome_wotlk-Patch, aber OPlates nutzt seine Nameplate-Einheiten nicht, daher fehlen dir sofortige Klassenfarben, Symbole und Rahmen bei jedem sichtbaren Spieler. Jetzt einschalten?";
L["|cffff3b3bWarmane: patch not allowed|r"] = "|cffff3b3bWarmane: Patch nicht erlaubt|r";
L["|cff40ff40detected|r"] = "|cff40ff40erkannt|r";
L["|cffff6060not detected|r"] = "|cffff6060nicht erkannt|r";
L["|cff40ff40in use|r"] = "|cff40ff40aktiv|r";
L["not in use"] = "nicht aktiv";
L["awesome_wotlk patch: "] = "awesome_wotlk-Patch: ";
L["Nameplate units: "] = "Nameplate-Einheiten: ";
L["off"] = "aus";
L["Everything"] = "Alles";
L["Healers only"] = "Nur Heiler";
L["Tanks only"] = "Nur Tanks";
L["Class icons only"] = "Nur Klassensymbole";
L["Spec icons only"] = "Nur Spez-Symbole";
L["Pets only"] = "Nur Begleiter";
L["Flag carriers only"] = "Nur Flaggenträger";
L["Crowd control only"] = "Nur Kontrolleffekte";
L["Buffs only"] = "Nur Buffs";
L["Debuffs only"] = "Nur Debuffs";
L["Pick which icons may appear. \"Crowd control only\" shows CC icons only (gone the moment the CC ends). \"Buffs only\" / \"Debuffs only\" show your listed spells (plus CC when \"Show crowd control\" is on). Options a mode doesn't use turn grey and keep their values."] = "Wähle, welche Symbole erscheinen dürfen. \"Nur Kontrolleffekte\" zeigt ausschließlich CC-Symbole (verschwinden, sobald der CC endet). \"Nur Buffs\" / \"Nur Debuffs\" zeigen deine gelisteten Zauber (plus CC, wenn \"Kontrolleffekte anzeigen\" aktiv ist). Optionen, die ein Modus nicht nutzt, werden grau und behalten ihre Werte.";
L["Seconds left, in the center of CC and aura icons. White from 1 minute, yellow under 1 minute, red from 5 seconds (then tenths). Only for effects with a known duration."] = "Verbleibende Sekunden in der Mitte von CC- und Aura-Symbolen. Weiß ab 1 Minute, gelb unter 1 Minute, rot ab 5 Sekunden (dann Zehntel). Nur bei Effekten mit bekannter Dauer.";
L["Class Filters"] = "Klassenfilter";
L["Spec Filters"] = "Spez-Filter";
L["Choose which classes show their class icon. A hidden class still shows its spec, healer/tank, CC and aura icons."] = "Wähle, welche Klassen ihr Klassensymbol zeigen. Eine ausgeblendete Klasse zeigt weiterhin Spez-, Heiler/Tank-, CC- und Aura-Symbole.";
L["Choose which specs show their spec icon. A hidden spec shows the class icon instead (when class icons are on and that class is not hidden)."] = "Wähle, welche Spezialisierungen ihr Spez-Symbol zeigen. Eine ausgeblendete Spez zeigt stattdessen das Klassensymbol (wenn Klassensymbole an sind und die Klasse nicht ausgeblendet ist).";
L["Nameplates"] = "Nameplates";
L["Friendly Plates"] = "Verbündete";
L["Clean circular icons for your allies."] = "Klare runde Symbole für deine Verbündeten.";
L["Essentials"] = "Grundlagen";
L["Friendly icons"] = "Symbole für Verbündete";
