L["Icon mode"] = "Symbolmodus";
L["Arenas & battlegrounds only"] = "Nur Arenen & Schlachtfelder";
L["Hide friendly icons everywhere else."] = "Verbündetensymbole überall sonst ausblenden.";
L["Identity"] = "Identität";
