L["The icon becomes the active CC while it lasts. CC always wins over buffs and debuffs."] = "Das Symbol wird zum aktiven CC, solange er anhält. CC hat immer Vorrang vor Buffs und Debuffs.";
L["Countdown in the icon"] = "Countdown im Symbol";
L["Buff & debuff lists"] = "Buff- & Debuff-Listen";
L["Let the spells you list below take the icon's place while active."] = "Lass die unten gelisteten Zauber das Symbol ersetzen, solange sie aktiv sind.";
